using System.Windows.Forms;

static class Program
{
    [STAThread]
    static void Main()
    {
        ApplicationConfiguration.Initialize();

        // .NET 9 breaking change: StatusStrip/ToolStrip default renderer changed
        // from Professional to System. Restore the .NET 8 behavior globally.
        ToolStripManager.RenderMode = ToolStripManagerRenderMode.Professional;

        Application.Run(new MainForm());
    }
}

using System.Windows.Forms;

class MainForm : Form
{
    private readonly StatusStrip _statusStrip;
    private readonly ToolStripStatusLabel _statusLabel;

    public MainForm()
    {
        Text = "WinForms App";

        _statusLabel = new ToolStripStatusLabel("Ready");
        _statusStrip = new StatusStrip();
        _statusStrip.Items.Add(_statusLabel);
        Controls.Add(_statusStrip);
    }
}

using System.Windows.Forms;
using System.Windows.Forms.Design;

/// <summary>
/// Wraps IWindowsFormsEditorService to guard against the .NET 9 breaking change
/// where DropDownControl(null) now throws ArgumentNullException.
/// </summary>
class SafeEditorService
{
    private readonly IWindowsFormsEditorService _editorService;

    public SafeEditorService(IWindowsFormsEditorService editorService)
    {
        _editorService = editorService;
    }

    public void ShowDropDown(Control? control)
    {
        // .NET 9: DropDownControl(null) throws ArgumentNullException.
        // Only call when a non-null control is provided.
        if (control is null)
            return;

        _editorService.DropDownControl(control);
    }
}

